"""Render the text companion from the same evidence and transfer-case sources as the deck."""
from html import escape as esc
from pathlib import Path
import json

def render(root):
 course=json.loads((root/'course.json').read_text());evidence=json.loads((root/'course-evidence.json').read_text());case=json.loads((root/'learning-check.json').read_text())
 out='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Study companion — Common Ground</title><style>body{background:#f2f6fc;color:#152f52;font:18px/1.6 Georgia,serif;max-width:760px;padding:30px 24px;margin:auto}h1{font-size:42px;line-height:1.15}h2{font-size:30px;line-height:1.25;margin-top:45px}h3{font-size:23px;line-height:1.3}a{color:#216b88;overflow-wrap:anywhere}li{margin-bottom:14px}.muted{color:#4c617b}.chapter{border-top:1px solid #c5d3e5;margin-top:35px}.answer{border-left:3px solid #c5d3e5;padding-left:18px}a:focus-visible{outline:3px solid #a1486d;outline-offset:4px}@page{size:A4;margin:20mm}@media print{body{background:white;padding:0;font-size:11pt;max-width:none}h1{font-size:28pt}h2{font-size:21pt;break-after:avoid}h3{font-size:15pt;break-after:avoid}li,.answer{break-inside:avoid}.new-page{break-before:page}.chapter{break-inside:avoid}a{font-size:10pt}a::after{content:' (' attr(href) ')';font-size:9pt}}</style><main><h1>Common Ground<br>Study companion</h1><p>Evidence notes and an optional written transfer check. This original introductory course is independently organized and does not provide the depth or full coverage of a social psychology textbook.</p><p>The chapter decks and recorded narration introduce the ideas. These additional notes distinguish general patterns from individual predictions. The written case has no recorded narration. Suggested answers follow the tasks; cover them until you have tried.</p><h2>Evidence and limits</h2><p>These are selected sources, not a systematic literature review. Some links provide an abstract rather than free full text. Open introductory readings remain linked in each deck.</p>'''
 for c in course:
  e=evidence[str(c['number'])];out+=f'<section class="chapter"><h3>{c["number"]}. {esc(c["title"])}</h3><p><strong>Goal:</strong> {esc(c["objective"])}</p><ul>'+''.join(f'<li>{esc(x)}</li>'for x in e['claims'])+f'</ul><p>{esc(e["note"])}</p><ul>'+''.join(f'<li><a href="{esc(x["url"],quote=True)}">{esc(x["title"])}</a><br><span class="muted">{esc(x["kind"])}</span></li>'for x in e['sources'])+'</ul></section>'
 out+=f'<section class="new-page"><h2>{esc(case["title"])}</h2><p>{esc(case["intro"])}</p><h3>The language club</h3>'+''.join(f'<p>{esc(x)}</p>'for x in case['paragraphs'])+'<h3>Write your reasoning</h3><ol>'+''.join(f'<li><strong>{esc(x["title"])}</strong><p>{esc(x["prompt"])}</p></li>'for x in case['tasks'])+'</ol></section><section class="new-page"><h2>Suggested reasoning</h2>'+''.join(f'<div class="answer"><h3>{i+1}. {esc(x["title"])}</h3><p>{esc(x["answer"])}</p><p>Revisit chapters {", ".join(map(str,x["chapters"]))}.</p></div>'for i,x in enumerate(case['tasks']))+'</section><section class="new-page"><h2>Assess your explanation</h2>'+''.join(f'<h3>{esc(x["title"])}</h3><p><strong>Stronger:</strong> {esc(x["strong"])}</p><p><strong>Needs development:</strong> {esc(x["developing"])}</p>'for x in case['rubric'])+f'<p>{esc(case["followup"])}</p></section></main></html>'
 return out
